<?php
require_once __DIR__ . '/_bootstrap.php';$id=(int)($_GET['id']??0);$orders=customerRows('SELECT * FROM orders WHERE id=? AND user_id=? LIMIT 1',[$id,$customerId]);$order=$orders[0]??null;$items=$order?customerRows('SELECT oi.*,p.name FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?',[$id]):[];customerPageStart('Order details','Orders');?><div class="cw-title"><div><h1>Order <?= $order?'#'.e($order['order_number']??$order['id']):'not found' ?></h1><p>Order status and fulfilment details.</p></div><a href="orders.php">← All orders</a></div><?php if(!$order):?><div class="cw-empty">This order does not exist or is not assigned to your account.</div><?php else:?><div class="cw-grid cw-grid-2"><section class="cw-card"><h2>Items</h2><table class="cw-table"><tr><th>Product</th><th>Qty</th><th>Price</th></tr><?php foreach($items as $i):?><tr><td><?=e($i['name']??'Product')?></td><td><?= (int)$i['quantity']?></td><td><?=e(formatPrice($i['unit_price']??0))?></td></tr><?php endforeach;?></table></section><section class="cw-card"><h2>Order summary</h2><p>Status <span class="badge" style="float:right"><?=e(ucfirst((string)$order['order_status']))?></span></p><p>Total <strong style="float:right"><?=e(formatPrice($order['total_amount']??0))?></strong></p><hr><h3>Shipping address</h3><p class="muted">Address is managed by the checkout flow.</p></section></div><?php endif;?><?php customerPageEnd();?>